use thinkthen::{Answer, Engine, Question};
let tt = Engine::from_env()?;

// the one line that gives the refund deadline
let policy = ["Returns need the original receipt.",
    "Refunds are issued within 30 days of purchase.",
    "Shipping is free on orders over $50.",
    "Gift cards cannot be exchanged for cash."];
let found = tt.find("Which line gives the refund deadline?",
    &policy)?;
if let Some(place) = found.index {
    println!("{}", policy[place]);
